class C_BA_String:
    @staticmethod
    def solve(n, k, x, s):
        res = []
        x -= 1
        i = n - 1
        while i >= 0:
            if s[i] == 'a':
                res.append('a')
            else:
                count = 1
                while i - count >= 0 and s[i] == s[i - count]:
                    count += 1
                base = count * k + 1
                for j in range(x % base):
                    res.append('b')
                x //= base
                i -= count - 1
            i -= 1
        print(''.join(res[::-1]))

    @staticmethod
    def main():
        import sys
        input = sys.stdin.read
        data = input().split()

