func solveCase(n int, ar []int) int {
	ans := 1<<31 - 1
	for j := 0; j < 3; j++ {
		for k := 0; k < 3; k++ {
			mod3 := make([][]int, 10)
			for i := range mod3 {
				mod3[i] = []int{0, 1<<31 - 1}
			}
			mod3[0][0] = 1
			mod3[0][1] = 0
			for l := 0; l <= j; l++ {
				for m := 0; m <= k; m++ {
					sum := l + m*2
					if sum < 10 {
						mod3[sum][0] = 1
						mod3[sum][1] = min(l+m, mod3[sum][1])
					}
				}
			}
			mx := 0
			for l := 0; l < n; l++ {
				mod := ar[l] % 3
				mn := 1<<31 - 1
				for m := mod; m <= ar[l] && m <= 9; m += 3 {
					if mod3[m][0] == 1 {
						mn = min((ar[l]-m)/3, mn)
					}
				}
				mx = max(mx, mn)
			}
			if mx != 1<<31-1 {
				ans = min(ans, mx+j+k)
			}
		}
	}
	return ans
}

