func main() {
	var n int
	fmt.Scan(&n)

	p := make([][2]int, n)
	r := make([][]int, n)
	for i := range r {
		r[i] = make([]int, n)
	}
	q := make([]int, n)

	scanner := bufio.NewScanner(os.Stdin)
	for i := 0; i < n; i++ {
		scanner.Scan()
		inputs := strings.Fields(scanner.Text())
		x, _ := strconv.Atoi(inputs[0])
		y, _ := strconv.Atoi(inputs[1])
		p[i] = [2]int{x, y}
	}

	ans := 0
	cnt := 0

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			gcd := func(a, b int) int {
				for b != 0 {
					a, b = b, a%b
				}
				return a
			}

			if math.Abs(float64(p[i][0]-p[j][0])) == 0 && math.Abs(float64(p[i][1]-p[j][1])) == 0 {
				continue
			}

			if gcd(int(math.Abs(float64(p[i][0]-p[j][0])), int(math.Abs(float64(p[i][1]-p[j][1])))%4) == 0 {
				cnt++
				r[i][j] = 1
				q[i]++
				ans += n - 2
			}
		}
	}

	for i := 0; i < n; i++ {
		for j := 1; j < n; j++ {
			if r[i][j] == 1 {
				ans -= q[j] * 2
			}
		}
	}

	fmt.Println(ans)
}

