func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscanf(reader, "%d %d\n", &n, &m)

	G := make([]string, n)
	for i := range G {
		G[i], _ = reader.ReadString('\n')
		G[i] = strings.TrimSpace(G[i])
	}

	F := []int{}
	for j := 0; j < m-1; j++ {
		v := false
		for i := 0; i < n-1; i++ {
			if G[i+1][j] == 'X' && G[i][j+1] == 'X' {
				v = true
				break
			}
		}
		if v {
			F = append(F, j)
		}
	}

	var Q int
	fmt.Fscanf(reader, "%d\n", &Q)

	for q := 0; q < Q; q++ {
		var x1, x2 int
		fmt.Fscanf(reader, "%d %d\n", &x1, &x2)
		x1--
		x2--

		v := true
		for _, f := range F {
			if x1 <= f && f < x2 {
				v = false
				break
			}
		}

		if v {
			fmt.Fprintln(writer, "YES")
		} else {
			fmt.Fprintln(writer, "NO")
		}
	}
