        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int gcdValue = gcd(Math.abs(p[i][0] - p[j][0]), Math.abs(p[i][1] - p[j][1]));
                if (gcdValue % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
