                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

