struct CBAString;

impl CBAString {
    fn solve(n: usize, k: usize, mut x: usize, s: &str) {
        let chars: Vec<char> = s.chars().collect();
        let mut res = String::new();
        x -= 1;
        let mut i = n - 1;

        while i != usize::MAX {
            if chars[i] == 'a' {
                res.push('a');
            } else {
                let mut count = 1;
                while i >= count + 1 && chars[i] == chars[i - count] {
                    count += 1;
                }
                let base = count * k + 1;
                for _ in 0..x % base {
                    res.push('b');
                }
                x /= base;
                i = i.checked_sub(count).unwrap_or(usize::MAX);
            }
            if i != usize::MAX {
                i -= 1;
            }
        }

        res.chars().rev().for_each(|c| print!("{}", c));
        println!();
    }
}

