struct D1620;

impl D1620 {
    fn process_cases(t: usize, reader: &mut dyn BufRead) {
        if t == 0 {
            return;
        }

        let mut buffer = String::new();
        reader.read_line(&mut buffer).unwrap();
        let n: usize = buffer.trim().parse().unwrap();

        buffer.clear();
        reader.read_line(&mut buffer).unwrap();
        let ar: Vec<i32> = buffer.trim().split_whitespace().map(|s| s.parse().unwrap()).collect();

        Self::solve_case(n, &ar);

        Self::process_cases(t - 1, reader);
    }

    fn solve_case(n: usize, ar: &[i32]) {
        let mut ans = i32::MAX;

        for j in 0..3 {
            for k in 0..3 {
                let mut mod3 = [[0, i32::MAX]; 10];
                mod3[0] = [1, 0];

                for l in 0..=j {
                    for m in 0..=k {
                        let sum = l + m * 2;
                        if sum < 10 {
                            mod3[sum][0] = 1;
                            mod3[sum][1] = mod3[sum][1].min(l as i32 + m as i32);
                        }
                    }
                }

                let mut mx = 0;
                for &x in ar {
                    let mod_val = x % 3;
                    let mut mn = i32::MAX;
                    for m in (mod_val..=9).step_by(3) {
                        if mod3[m as usize][0] == 1 {
                            mn = mn.min((x - m) / 3);
                        }
                    }
                    mx = mx.max(mn);
                }

                if mx != i32::MAX {
                    ans = ans.min(mx + j as i32 + k as i32);
                }
            }
        }

        println!("{}", ans);
    }
}

