            for k in 0..<3 {
                var mod3 = Array(repeating: Array(repeating: 0, count: 2), count: 10)
                mod3[0][0] = 1
                mod3[0][1] = 0

                for l in 0...j {
                    for m in 0...k {
                        let sum = l + m * 2
                        if sum < 10 {
                            mod3[sum][0] = 1
                            mod3[sum][1] = min(l + m, mod3[sum][1])
