class FastIO {
    private buffer: string = '';
    private index: number = 0;
    private reader: NodeJS.ReadStream = process.stdin;
    private writer: NodeJS.WriteStream = process.stdout;

    constructor() {
        this.reader.on('data', (chunk) => {
            this.buffer += chunk.toString();
        });
    }

    read(): string {
        let result = '';
        while (true) {
            const newlineIndex = this.buffer.indexOf('\n', this.index);
            if (newlineIndex !== -1) {
                result += this.buffer.substring(this.index, newlineIndex + 1);
                this.index = newlineIndex + 1;
                return result;
            } else {
                result += this.buffer.substring(this.index);
                this.index = this.buffer.length;
            }
            const chunk = this.reader.read();
            if (chunk === null) break;
            this.buffer += chunk.toString();
        }
        return result;
    }

    readline(): string {
        const newlineIndex = this.buffer.indexOf('\n', this.index);
        if (newlineIndex !== -1) {
            const line = this.buffer.substring(this.index, newlineIndex);
            this.index = newlineIndex + 1;
            return line;
        } else {
            let line = this.buffer.substring(this.index);
            this.index = this.buffer.length;
            while (!line.endsWith('\n')) {
                const chunk = this.reader.read();
                if (chunk === null) break;
                line += chunk.toString();
            }
            return line.replace(/\n$/, '');
        }
    }

    write(s: string): void {
        this.writer.write(s);
    }

    flush(): void {
        this.writer.flush();
    }
}

