const BUFSIZE = 8192;

class FastIO {
    private fd: number;
    private buffer: Uint8Array;
    private writable: boolean;

    constructor(fileDescriptor: number) {
        this.fd = fileDescriptor;
        this.buffer = new Uint8Array(BUFSIZE);
        this.writable = fileDescriptor !== process.stdin.fd;
    }

    async read(): Promise<string> {
        let b: number[] = [];
        while (true) {
            const buf = new Uint8Array(BUFSIZE);
            const n = await fs.read(this.fd, buf, 0, BUFSIZE, null);
            if (n === 0) break;
            b.push(...buf.subarray(0, n));
        }
        return new TextDecoder().decode(new Uint8Array(b));
    }

    async readLine(): Promise<string> {
        let b: number[] = [];
        while (true) {
            const buf = new Uint8Array(BUFSIZE);
            const n = await fs.read(this.fd, buf, 0, BUFSIZE, null);
            if (n === 0) break;
            b.push(...buf.subarray(0, n));
            if (b.includes('\n'.charCodeAt(0))) break;
        }
        return new TextDecoder().decode(new Uint8Array(b)).split('\n')[0];
    }

    async flush(): Promise<void> {
        if (this.writable) {
            await fs.write(process.stdout.fd, this.buffer, 0, this.buffer.length, null);
            this.buffer = new Uint8Array(BUFSIZE);
        }
    }
}

