public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer;
        PrintWriter writer = new PrintWriter(System.out);

        int t = Integer.parseInt(reader.readLine());
        while (t-- > 0) {
            int n = Integer.parseInt(reader.readLine());
            long[] dp1 = new long[n + 2];
            long[] dp2 = new long[n + 2];
            dp1[0] = 1;

            tokenizer = new StringTokenizer(reader.readLine());
            for (int i = 0; i < n; i++) {
                int num = Integer.parseInt(tokenizer.nextToken());
                dp1[num + 1] = (dp1[num + 1] * 2) % MOD;
                dp1[num + 1] = (dp1[num + 1] + dp1[num]) % MOD;
                if (num > 0) {
                    dp2[num - 1] = (dp2[num - 1] * 2) % MOD;
                    dp2[num - 1] = (dp2[num - 1] + dp1[num - 1]) % MOD;
                }
                dp2[num + 1] = (dp2[num + 1] * 2) % MOD;
            }

            long ans = 0;
            for (int i = 0; i < n + 2; i++) {
                ans = (ans + dp1[i] + dp2[i]) % MOD;
            }
            writer.println(ans > 0 ? ans - 1 : MOD - 1);
        }

        reader.close();
        writer.close();
    }
}

