public class Main {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st;
		PrintWriter pw = new PrintWriter(System.out);

		try {
			int t = Integer.parseInt(br.readLine());

			for(int cases = 0; cases < t; cases++) {
				st = new StringTokenizer(br.readLine());
				int n = Integer.parseInt(st.nextToken());
				int d = Integer.parseInt(st.nextToken());

				int[] A = new int[n];
				st = new StringTokenizer(br.readLine());
				for(int i = 0; i < n; i++)
					A[i] = Integer.parseInt(st.nextToken());

				int[] ANS = new int[n];
				for(int i = 0; i < n; i++) {
					ANS[i] = -1;
				}

				for(int i = 0; i < n; i++) {
					if(A[i] == 0) {
						ANS[i] = 0;

						int x = (i + d)%n;
						int now = 1;
						while(true) {
							if(ANS[x] > 0 || A[x] == 0)
								break;
							else {
								ANS[x] = now;
								now++;
								x = (x + d)%n;
							}
						}
					}
				}

				boolean hasMinusOne = false;
				int maxValue = -1;
				for(int i = 0; i < n; i++) {
					if(ANS[i] == -1) {
						hasMinusOne = true;
						break;
					}
					maxValue = Math.max(maxValue, ANS[i]);
				}

				if(hasMinusOne)
					pw.println(-1);
				else
					pw.println(maxValue);
			}
		}
		finally {
			br.close();
			pw.flush();
			pw.close();
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO(System.in, System.out);
        int t = inp(io);
        while (t-- > 0) {
            int n = inp(io);
            List<Integer> l = inlt(io);
            if (n % 2 == 0) {
                io.write("YES\n");
            } else {
                boolean flag = false;
                for (int j = 0; j < n - 1; j++) {
                    if (l.get(j) >= l.get(j + 1)) {
                        flag = true;
                        break;
                    }
                }
                if (flag) {
                    io.write("YES\n");
                } else {
                    io.write("NO\n");
                }
            }
        }
        io.flush();
    }

    private static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferPointer;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = BUFSIZE;
            this.buffer = new byte[bufferSize];
            this.bufferPointer = bufferSize;
        }

        private int read() throws IOException {
            if (bufferPointer == bufferSize) {
                bufferPointer = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferPointer++];
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    private static int inp(FastIO io) throws IOException {
        return Integer.parseInt(io.readLine());
    }

    private static List<Integer> inlt(FastIO io) throws IOException {
        String[] parts = io.readLine().split("\\s+");
        List<Integer> list = new ArrayList<>();
        for (String part : parts) {
            list.add(Integer.parseInt(part));
        }
        return list;
    }
}

