        vec.clear();
        ans.clear();
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '*') {
                cnt++;
            } else {
                vec.add((int) (cnt * k));
                cnt = 0;
            }
