                    }
                    for (int l = 0; l <= j; l++) {
                        for (int m = 0; m <= k; m++) {
                            mod3[l + m * 2][0] = 1;
                            mod3[l + m * 2][1] = Math.min(l + m, mod3[l + m * 2][1]);
