public class Main {

    public static void main(String[] args) throws IOException {
        sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int N = sc.nextInt();
        while (N > 0) {
            solve(out);
            N--;
        }
        out.flush();
    }

    private static void solve(PrintWriter out) throws IOException {
        int n = sc.nextInt(), m = sc.nextInt(), k = sc.nextInt();

        int b_t = n % m;
        int b_p = n / m + 1;

        int next_b = 1, next_s = 1;

        if (b_t == 0) {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < n / m; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) next_b = 1;
                        else next_b++;
                    }
                    out.println();
                }
            }
        } else {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < b_t; j++) {
                    out.print(n / m + 1 + " ");
                    for (int play = 0; play < b_p; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) next_b = 1;
                        else next_b++;
                    }
                    out.println();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < b_p - 1; play++) {
                        out.print(next_s + " ");
                        if (next_s == n) next_s = 1;
                        else next_s++;
                    }
                    out.println();
                }
            }
        }
        out.println();
    }

    static Scanner sc;

    static class Scanner {

        BufferedReader br;
        StringTokenizer st;

        public Scanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

