        private byte[] buffer;
        private int bufferSize;
        private int bufferIndex;

        public FastIO(Stream stream)
        {
            reader = stream;
            buffer = new byte[BUFSIZE];
            bufferSize = 0;
            bufferIndex = 0;
        }

        private void FillBuffer()
        {
            bufferSize = reader.Read(buffer, 0, BUFSIZE);
            bufferIndex = 0;
        }

        public string ReadLine()
        {
            var line = new List<byte>();
            while (true)
            {
                if (bufferIndex >= bufferSize)
                {
                    FillBuffer();
                    if (bufferSize == 0) break;
                }
                if (buffer[bufferIndex] == '\n')
                {
                    bufferIndex++;
                    break;
                }
                line.Add(buffer[bufferIndex++]);
            }
            return System.Text.Encoding.UTF8.GetString(line.ToArray());
        }

        public void Write(string s)
        {
            var bytes = System.Text.Encoding.UTF8.GetBytes(s);
            reader.Write(bytes, 0, bytes.Length);
        }

        public void Flush()
        {
            reader.Flush();
        }
    }

    static FastIO stdin;
    static FastIO stdout;

    static void Main(string[] args)
    {
        stdin = new FastIO(Console.OpenStandardInput());
        stdout = new FastIO(Console.OpenStandardOutput());

        int t = Inp();
        for (int i = 0; i < t; i++)
        {
            int n = Inp();
            List<int> l = Inlt();
            if (n % 2 == 0)
            {
                Stdout.Write("YES\n");
            }
            else
            {
                bool flag = false;
                for (int j = 0; j < n - 1; j++)
                {
                    if (l[j] >= l[j + 1])
                    {
                        flag = true;
                        break;
                    }
                }
                if (flag)
                {
                    Stdout.Write("YES\n");
                }
                else
                {
                    Stdout.Write("NO\n");
                }
            }
        }
        Stdout.Flush();
    }

    static string Input()
    {
        return Stdin.ReadLine().TrimEnd('\r', '\n');
    }

    static int Inp()
    {
        return int.Parse(Input());
    }

    static string Inps()
    {
        return Input().Trim();
    }

    static List<int> Inlt()
    {
        return Array.ConvertAll(Input().Split(' '), int.Parse).ToList();
    }

    static List<string> Insr()
    {
        return Input().Trim().Select(c => c.ToString()).ToList();
    }

    static List<int> Invr()
    {
        return Array.ConvertAll(Input().Split(' '), int.Parse).ToList();
    }
}

