    {
        vec.Clear();
        ans.Clear();
        int cnt = 0;
        for (int i = 0; i < n; i++)
        {
            if (s[i] == '*')
                cnt++;
            else
            {
                vec.Add((int)(cnt * k));
                cnt = 0;
            }
        }
        vec.Add((int)(cnt * k));
        for (int i = vec.Count - 1; i >= 0; i--)
        {
            ans.Add((int)(x % (vec[i] + 1)));
            x /= (vec[i] + 1);
        }
