using System;
using System.Numerics;

class Program
{
    const int Mod = 998244353;

    static (int, BigInteger, BigInteger) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        var (g, y, x) = Egcd(b % a, a);
        return (g, x - (b / a) * y, y);
    }

    static BigInteger Modinv(int a, int m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
            throw new InvalidOperationException("modular inverse does not exist");
        return ((x % m + m) % m);
    }

    static BigInteger Choose(int n, int k, int p)
    {
        if (k == 0 || n < k)
            return 1;
        BigInteger x = 1;
        for (int i = 0; i < k; i++)
        {
            x = x * (n - i) % p;
            int d = i + 1;
            x = x * Modinv(d, p) % p;
        }
        return x;
    }

    static void Solve()
    {
        var reader = Console.In;
        int n = int.Parse(reader.ReadLine());

        bool wbPoss = true;
        bool bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool anyBadPoss = true;

        for (int i = 0; i < n; i++)
        {
            string s = reader.ReadLine();
            if (s[0] == 'B')
            {
                b++;
                wbPoss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bwPoss = false;
            }
            else if (s[0] == '?')
                q++;

            if (s[1] == 'B')
            {
                b++;
                bwPoss = false;
            }
            else if (s[1] == 'W')
            {
                w++;
                wbPoss = false;
            }
            else if (s[1] == '?')
                q++;

            if (s == "??" || s[0] != s[1])
                free++;
            else
                anyBadPoss = false;
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }

        BigInteger numBadPoss;
        if (anyBadPoss)
        {
            numBadPoss = BigInteger.ModPow(2, free, Mod);
            if (wbPoss)
                numBadPoss--;
            if (bwPoss)
                numBadPoss--;
        }
        else
            numBadPoss = 0;

        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    const int BUFSIZE = 8192;

    class FastIO
    {
        private Stream stream;
        private byte[] buffer;
        private bool writable;
        private int bufferSize;
        private int bufferIndex;

        public FastIO(Stream stream, bool writable = false)
        {
            this.stream = stream;
            this.writable = writable;
            this.bufferSize = BUFSIZE;
            this.buffer = new byte[bufferSize];
            this.bufferIndex = bufferSize;
        }

        private void FillBuffer()
        {
            bufferIndex = 0;
            bufferSize = stream.Read(buffer, 0, bufferSize);
        }

        public char ReadChar()
        {
            if (bufferIndex >= bufferSize)
                FillBuffer();
            return (char)buffer[bufferIndex++];
        }

        public string ReadLine()
        {
            var list = new List<char>();
            while (true)
            {
                char c = ReadChar();
                if (c == '\n' || c == '\r')
                    break;
                list.Add(c);
            }
            return new string(list.ToArray());
        }

        public int ReadInt()
        {
            bool negative = false;
            int num = 0;
            char c;
            while ((c = ReadChar()) < '0' || c > '9')
                if (c == '-')
                    negative = true;
            do
            {
                num *= 10;
                num += c - '0';
            } while ((c = ReadChar()) >= '0' && c <= '9');
            return negative ? -num : num;
        }

        public void Write(string s)
        {
            if (writable)
                stream.Write(System.Text.Encoding.ASCII.GetBytes(s), 0, s.Length);
        }

        public void WriteLine(string s)
        {
            Write(s + "\n");
        }
    }

    static FastIO stdin = new FastIO(Console.OpenStandardInput());
    static FastIO stdout = new FastIO(Console.OpenStandardOutput(), true);

    static int Inp()
    {
        return stdin.ReadInt();
    }

    static string Inps()
    {
        return stdin.ReadLine();
    }

    static List<int> Inlt()
    {
        var list = new List<int>();
        string[] parts = stdin.ReadLine().Split(' ');
        foreach (var part in parts)
            list.Add(int.Parse(part));
        return list;
    }

    static List<string> Insr()
    {
        return new List<char>(stdin.ReadLine()).ConvertAll(c => c.ToString());
    }

    static IEnumerable<int> Invr()
    {
        string[] parts = stdin.ReadLine().Split(' ');
        foreach (var part in parts)
            yield return int.Parse(part);
    }

    static void Main(string[] args)
    {
        int t = Inp();
        while (t-- > 0)
        {
            int n = Inp();
            var l = Inlt();
            int s = l[0];
            for (int i = 1; i < n; i++)
                s &= l[i];
            stdout.WriteLine(s.ToString());
        }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var reader = new System.IO.StreamReader(Console.OpenStandardInput());
        int n = int.Parse(reader.ReadLine());

        List<(int, int)> points = new List<(int, int)>();
        for (int i = 0; i < n; i++)
        {
            string[] parts = reader.ReadLine().Split(' ');
            int x = int.Parse(parts[0]);
            int y = int.Parse(parts[1]);
            points.Add((x, y));
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int dx = Math.Abs(points[i].Item1 - points[j].Item1);
                int dy = Math.Abs(points[i].Item2 - points[j].Item2);
                if (Gcd(dx, dy) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

using System;
using System.IO;

class Program
{
    private static int N;
    private static Scanner sc;
    private static StreamWriter outStream = new StreamWriter(Console.OpenStandardOutput());

    static void Main(string[] args)
    {
        sc = new Scanner(Console.OpenStandardInput());
        N = sc.NextInt();
        while (N > 0)
        {
            Solve();
            N--;
        }
        outStream.Flush();
    }

    private static void Solve()
    {
        int n = sc.NextInt();
        int m = sc.NextInt();
        int k = sc.NextInt();

        int b_t = n % m;
        int b_p = n / m + 1;
        int next_b = 1;
        int next_s = 1;

        if (b_t == 0)
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    outStream.Write((n / m) + " ");
                    for (int play = 0; play < n / m; play++)
                    {
                        outStream.Write(next_b + " ");
                        if (next_b == n)
                            next_b = 1;
                        else
                            next_b++;
                    }
                    outStream.WriteLine();
                }
            }
        }
        else
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < b_t; j++)
                {
                    outStream.Write((n / m + 1) + " ");
                    for (int play = 0; play < b_p; play++)
                    {
                        outStream.Write(next_b + " ");
                        if (next_b == n)
                            next_b = 1;
                        else
                            next_b++;
                    }
                    outStream.WriteLine();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++)
                {
                    outStream.Write((n / m) + " ");
                    for (int play = 0; play < b_p - 1; play++)
                    {
                        outStream.Write(next_s + " ");
                        if (next_s == n)
                            next_s = 1;
                        else
                            next_s++;
                    }
                    outStream.WriteLine();
                }
            }
        }
        outStream.WriteLine();
    }

    public class Scanner
    {
        private readonly StreamReader reader;
        private string[] tokens;
        private int tokenIndex;

        public Scanner(Stream stream)
        {
            reader = new StreamReader(stream);
            tokens = new string[0];
            tokenIndex = 0;
        }

        private void ReadNextLine()
        {
            string line = reader.ReadLine();
            if (line != null)
            {
                tokens = line.Split(' ');
                tokenIndex = 0;
            }
        }

        public string Next()
        {
            if (tokenIndex >= tokens.Length)
            {
                ReadNextLine();
            }
            return tokens[tokenIndex++];
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public double NextDouble()
        {
            return double.Parse(Next());
        }

        public int[] ReadArray(int n)
        {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = NextInt();
            return a;
        }

        public string NextLine()
        {
            if (tokenIndex >= tokens.Length)
            {
                return reader.ReadLine();
            }
            else
            {
                string line = tokens[tokenIndex++];
                while (tokenIndex < tokens.Length)
                {
                    line += " " + tokens[tokenIndex++];
                }
                ReadNextLine();
                return line;
            }
        }
    }
}

