fn solve(_n: i64, k: i64, mut x: i64, s: &str) -> String {
    let mut vec = Vec::new();
    let mut ans = Vec::new();
    let mut cnt = 0;
    for c in s.chars() {
        if c == '*' {
            cnt += 1;
        } else {
            vec.push(cnt * k);
            cnt = 0;
        }
    }
    vec.push(cnt * k);
    for &v in vec.iter().rev() {
        ans.push((x % (v + 1)) as usize);
        x /= v + 1;
    }
    let sr = ans.len();
    for _ in sr..vec.len() {
        ans.push(0);
    }
    let mut fin = String::new();
    for &a in ans.iter().rev() {
        fin.push_str(&"b".repeat(a));
        if !fin.is_empty() && fin.len() != s.len() {
            fin.push('a');
        }
    }
    fin
}

