fn egcd(a: i64, b: i64) -> (i64, i64, i64) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, x, y) = egcd(b % a, a);
        (g, y - (b / a) * x, x)
    }
}

fn modinv(a: i64, m: i64) -> i64 {
    let (_, x, _) = egcd(a, m);
    ((x % m + m) % m)
}

fn choose(n: i64, k: i64, p: i64) -> i64 {
    if k == 0 || n < k {
        return 1;
    }
    let mut x = 1;
    for i in 0..k {
        x = x * (n - i) % p;
        let d = i + 1;
        x = x * modinv(d, p) % p;
    }
    x
}

fn pow(mut base: i64, mut exp: i64, mod_val: i64) -> i64 {
    let mut result = 1;
    while exp > 0 {
        if exp % 2 == 1 {
            result = result * base % mod_val;
        }
        exp >>= 1;
        base = base * base % mod_val;
    }
    result
}

