const int BUFSIZE = 8192;

class FastIO {
private:
    std::istream& reader;
    std::ostream& writer;
    char buffer[BUFSIZE];
    size_t bufferSize;
    size_t bufferPos;

public:
    FastIO(std::istream& in, std::ostream& out) : reader(in), writer(out), bufferSize(0), bufferPos(0) {}

    std::string read() {
        std::ostringstream oss;
        while (true) {
            if (bufferPos >= bufferSize) {
                bufferSize = reader.read(buffer, BUFSIZE).gcount();
                bufferPos = 0;
                if (bufferSize == 0) break;
            }
            char c = buffer[bufferPos++];
            if (c == '\n' || reader.eof()) {
                break;
            }
            oss << c;
        }
        return oss.str();
    }

    std::string readLine() {
        std::ostringstream oss;
        while (true) {
            if (bufferPos >= bufferSize) {
                bufferSize = reader.read(buffer, BUFSIZE).gcount();
                bufferPos = 0;
                if (bufferSize == 0) break;
            }
            char c = buffer[bufferPos++];
            if (c == '\n' || reader.eof()) {
                break;
            }
            oss << c;
        }
        return oss.str();
    }

    void write(const std::string& s) {
        writer << s;
    }

    void flush() {
        writer.flush();
    }
};

