const int mod = 998244353;

std::tuple<int, int, int> egcd(int a, int b) {
    if (a == 0) {
        return {b, 0, 1};
    }
    auto [g, y, x] = egcd(b % a, a);
    return {g, x - (b / a) * y, y};
}

int modinv(int a, int m) {
    auto [g, x, _] = egcd(a, m);
    if (g != 1) {
        throw std::runtime_error("modular inverse does not exist");
    }
    return (x % m + m) % m;
}

int choose(int n, int k, int p) {
    if (k == 0 || n < k) {
        return 1;
    }
    long long x = 1;
    for (int i = 0; i < k; ++i) {
        x = x * (n - i) % p;
        int d = i + 1;
        x = x * modinv(d, p) % p;
    }
    return static_cast<int>(x);
}

void solve() {
    int n;
    std::cin >> n;

    bool wb_poss = true;
    bool bw_poss = true;
    int w = 0;
    int b = 0;
    int q = 0;
    int free = 0;
    bool any_bad_poss = true;

    for (int i = 0; i < n; ++i) {
        std::string s;
        std::cin >> s;
        if (s[0] == 'B') {
            b++;
            wb_poss = false;
        } else if (s[0] == 'W') {
            w++;
