        } else if (s[1] == 'W') {
            w++;
            wb_poss = false;
        } else if (s[1] == '?') {
            q++;
        }
        if (s == "??" ) {
            free++;
        } else if (s[0] == s[1]) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - w;
    if (w_needed > q || w_needed < 0) {
        std::cout << 0 << '\n';
        return;
    }

    int num_bad_poss;
    if (any_bad_poss) {
        long long num_free_combinations = 1LL << free;
        num_bad_poss = static_cast<int>(num_free_combinations % mod);
        if (wb_poss) {
