class FastIO {
public:
    FILE* fd;
    char buffer[BUFSIZE];
    bool writable;

    FastIO(FILE* _fd) : fd(_fd), writable(_fd != stdin) {}

    std::string read() {
        std::string result;
        size_t bytesRead;
        do {
            bytesRead = fread(buffer, 1, BUFSIZE, fd);
            result.append(buffer, bytesRead);
        } while (bytesRead == BUFSIZE);
        return result;
    }

    std::string readline() {
        std::string result;
        char c;
        while (fread(&c, 1, 1, fd) && c != '\n') {
            result += c;
        }
        return result;
    }

    void flush() {
        if (writable) {
            fwrite(buffer, 1, sizeof(buffer), stdout);
        }
    }
};

class IOWrapper {
public:
    FastIO fastio;
    bool writable;

    IOWrapper(FILE* _fd) : fastio(_fd), writable(_fd != stdin) {}

    std::string read() {
        return fastio.readline();
    }

    std::string readline() {
        return fastio.readline();
    }

    void flush() {
        if (writable) {
            fflush(stdout);
        }
    }
};

