    var q = 0
    var free = 0
    var any_bad_poss = true

    for _ in 0..<n {
        guard let s = readLine() else { return }
        if s.first == "B" {
            b += 1
            wb_poss = false
        } else if s.first == "W" {
            w += 1
            bw_poss = false
        } else if s.first == "?" {
            q += 1
        }
        if s.dropFirst().first == "B" {
            b += 1
            bw_poss = false
        } else if s.dropFirst().first == "W" {
            w += 1
            wb_poss = false
        } else if s.dropFirst().first == "?" {
            q += 1
        }
        if s == "??" {
            free += 1
        } else if s.first == s.dropFirst().first {
            any_bad_poss = false
        }
    }

    let w_needed = n - w
    if w_needed > q || w_needed < 0 {
        print(0)
        return
    }

    var num_bad_poss: Int
    if any_bad_poss {
        num_bad_poss = pow(2, free, mod)
        if wb_poss {
            num_bad_poss -= 1
        }
        if bw_poss {
            num_bad_poss -= 1
        }
    } else {
        num_bad_poss = 0
    }

    print((choose(q, w_needed, mod) - num_bad_poss + mod) % mod)
}

func pow(_ base: Int, _ exp: Int, _ mod: Int) -> Int {
    var result = 1
    var base = base
    var exp = exp
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * base) % mod
        }
        exp >>= 1
        base = (base * base) % mod
    }
    return result
}

