let BUFSIZE = 8192

class FastIO {
    private let fd: FileHandle
    private var buffer: Data
    private let writable: Bool

    init(file: FileHandle) {
        self.fd = file
        self.buffer = Data()
        self.writable = file !== FileHandle.standardInput
    }

    func read() -> String {
        var data = Data()
        while true {
            let chunk = fd.readData(ofLength: BUFSIZE)
            if chunk.isEmpty {
                break
            }
            data.append(chunk)
        }
        return String(data: data, encoding: .utf8) ?? ""
    }

    func readLine() -> String {
        var data = Data()
        while true {
            let chunk = fd.readData(ofLength: BUFSIZE)
            if chunk.isEmpty {
                break
            }
            data.append(chunk)
            if chunk.contains(where: { $0 == 10 }) {
                break
            }
        }
        return String(data: data, encoding: .utf8) ?? ""
    }

    func flush() {
        if writable {
            fd.write(buffer)
            buffer.removeAll()
        }
    }
}

class IOWrapper {
    private let buffer: Data
    private let writable: Bool

    init(file: FileHandle) {
        self.buffer = file.availableData
        self.writable = file !== FileHandle.standardInput
