    func read() -> String {
        let line = String(data: buffer, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return line
    }

    func readLine() -> String {
        let line = String(data: buffer, encoding: .utf8) ?? ""
        return line
    }

    func flush() {
        if writable {
            FileHandle.standardOutput.synchronizeFile()
        }
    }
}

