class Dsu:
    def __init__(self, n):
        self.parent = list(range(n + 1))

    def make_set(self):
        for i in range(1, len(self.parent)):
            self.parent[i] = i

    def find_parent(self, node):
        if node == self.parent[node]:
            return node
        self.parent[node] = self.find_parent(self.parent[node])
        return self.parent[node]

    def union(self, u, v):
        u_parent = self.find_parent(u)
        v_parent = self.find_parent(v)

        if u_parent != v_parent:
            self.parent[v_parent] = u_parent
            return 0
        else:
            return -1

    def check_component(self, u, v):
        if self.find_parent(u) != self.find_parent(v):
            print("Both belongs to different components")
        else:
            print("same component")

