import * as readline from 'readline';

class FastReader {
    private rl: readline.Interface;
    private buffer: string[] | null = null;

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
            terminal: false
        });
    }

    async next(): Promise<string> {
        if (this.buffer && this.buffer.length > 0) {
            return this.buffer.shift()!;
        }
        return new Promise((resolve) => {
            this.rl.once('line', (line) => {
                this.buffer = line.split(/\s+/);
                resolve(this.buffer.shift()!);
            });
        });
    }

    async nextInt(): Promise<number> {
        return parseInt(await this.next(), 10);
    }

    async nextLong(): Promise<number> {
        return parseFloat(await this.next());
    }

    async nextDouble(): Promise<number> {
        return parseFloat(await this.next());
    }

    async nextLine(): Promise<string> {
        if (this.buffer && this.buffer.length > 0) {
            return this.buffer.join(' ');
        }
        return new Promise((resolve) => {
            this.rl.once('line', (line) => {
                resolve(line);
            });
        });
    }
}

function reverse(a: number[], r: number): void {
    for (let i = 0; i <= Math.floor(r / 2); i++) {
        let l = i;
        let h = r - i;
        [a[l], a[h]] = [a[h], a[l]];
    }
}

