const BUFSIZE = 8192;

class FastIO {
    private inputStream: NodeJS.ReadStream;
    private outputStream: NodeJS.WriteStream;
    private buffer: Buffer;
    private bufferSize: number;
    private bufferIndex: number;

    constructor(inputStream: NodeJS.ReadStream, outputStream: NodeJS.WriteStream) {
        this.inputStream = inputStream;
        this.outputStream = outputStream;
        this.buffer = Buffer.alloc(BUFSIZE);
        this.bufferSize = 0;
        this.bufferIndex = 0;
    }

    public async readLine(): Promise<string> {
        const chunks: Uint8Array[] = [];
        while (true) {
            if (this.bufferIndex >= this.bufferSize) {
                this.bufferSize = await new Promise<number>((resolve, reject) => {
                    this.inputStream.read(this.buffer, 0, BUFSIZE, null, (err, bytesRead) => {
                        if (err) reject(err);
                        else resolve(bytesRead || 0);
                    });
                });
                this.bufferIndex = 0;
            }
            if (this.bufferSize === 0) break;

            const newlineIndex = this.buffer.indexOf('\n', this.bufferIndex);
            if (newlineIndex >= 0) {
                chunks.push(this.buffer.subarray(this.bufferIndex, newlineIndex + 1));
                this.bufferIndex = newlineIndex + 1;
                break;
            } else {
                chunks.push(this.buffer.subarray(this.bufferIndex, this.bufferSize));
                this.bufferIndex = this.bufferSize;
            }
        }
        return Buffer.concat(chunks).toString('ascii').trimEnd('\r\n');
    }

    public writeLine(value: number): void {
        this.outputStream.write(`${value}\n`);
    }
}

