public class Main {
    private static final int MOD = 998244353;
    private static final int N = (int) 1e9 + 7;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());
        while (t-- > 0) {
            int n = Integer.parseInt(br.readLine());
            long[] dp1 = new long[n + 2];
            long[] dp2 = new long[n + 2];
            dp1[0] = 1;
            for (int i : Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray()) {
                dp1[i + 1] = (dp1[i + 1] << 1) % MOD;
                dp1[i + 1] = (dp1[i + 1] + dp1[i]) % MOD;
                if (i > 0) {
                    dp2[i - 1] = (dp2[i - 1] << 1) % MOD;
                    dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % MOD;
                }
                dp2[i + 1] = (dp2[i + 1] << 1) % MOD;
            }

            long ans = 0;
            for (int i = 0; i <= n + 1; i++) {
                ans = (ans + dp1[i] + dp2[i]) % MOD;
            }

            System.out.println((ans - 1 + MOD) % MOD);
        }
    }
}

