public class Main {

    public static void main(String[] args) {
        FastReader input = new FastReader();
        int T = input.nextInt();
        while (T-- > 0) {
            int n = input.nextInt();
            int[] a = new int[n];
            int flag = 0;
            for (int i = 0; i < n; i++) {
                a[i] = input.nextInt();
                int p = i + 1;
                if (p % 2 != a[i] % 2) {
                    flag = 1;
                }
            }
            if (flag == 1) {
                System.out.println(-1);
            } else {
                List<Integer> list = new ArrayList<>();
                for (int i = n; i > 1; i -= 2) {
                    int in1 = 0, in2 = 0;
                    for (int j = 0; j < n; j++) {
                        if (a[j] == i) in1 = j;
                        else if (a[j] == i - 1) in2 = j;
                    }
                    reverse(a, in1);
                    if (in1 > in2) {
                        in2 = in1 - in2;
                    }
                    reverse(a, in2 - 1);
                    reverse(a, in2 + 1);
                    reverse(a, 2);
                    reverse(a, i - 1);
                    list.add(in1 + 1);
                    list.add(in2);
                    list.add(in2 + 2);
                    list.add(3);
                    list.add(i);
                }
                System.out.println(list.size());
                for (int i = 0; i < list.size(); i++) {
                    System.out.print(list.get(i) + " ");
                }
                System.out.println();
            }
        }
    }

    public static void reverse(int[] a, int r) {
        for (int i = 0; i <= r / 2; i++) {
            int l = i, h = r - i;
            int t = a[l];
            a[l] = a[h];
            a[h] = t;
        }
    }

    static class FastReader {
        BufferedReader br;
        String[] st;
        int index;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new String[0];
            index = 0;
        }

        String next() {
            if (index >= st.length) {
                try {
                    st = br.readLine().split(" ");
                    index = 0;
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st[index++];
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

