public class Main {

    private static FastIO input = new FastIO(System.in, System.out);

    public static void main(String[] args) throws IOException {
        int t = inp();
        while (t-- > 0) {
            int n = inp();
            int[] l = inlt();
            if (n % 2 == 0) {
                print("YES");
            } else {
                boolean flag = false;
                for (int j = 0; j < n - 1; j++) {
                    if (l[j] >= l[j + 1]) {
                        flag = true;
                        break;
                    }
                }
                if (flag) {
                    print("YES");
                } else {
                    print("NO");
                }
            }
        }
    }

    private static int inp() throws IOException {
        return Integer.parseInt(input.readLine());
    }

    private static String inps() throws IOException {
        return input.readLine().trim();
    }

    private static int[] inlt() throws IOException {
        String[] parts = input.readLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    private static char[] insr() throws IOException {
        return input.readLine().toCharArray();
    }

    private static void print(Object... args) throws IOException {
        String sep = " ";
        String end = "\n";
        for (int i = 0; i < args.length; i++) {
            if (i != 0) {
                input.write(sep.getBytes());
            }
            input.write(args[i].toString().getBytes());
        }
        input.write(end.getBytes());
        input.flush();
    }

    static class FastIO extends OutputStream {
        private InputStream in;
        private OutputStream out;
        private byte[] buffer = new byte[8192];
        private int bufferSize = 0, bufferIndex = 0;

        public FastIO(InputStream in, OutputStream out) {
            this.in = in;
            this.out = out;
        }

        @Override
        public void write(int b) throws IOException {
            out.write(b);
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        private int read() throws IOException {
            if (bufferSize == 0) {
                bufferSize = in.read(buffer);
                bufferIndex = 0;
            }
            if (bufferSize <= 0) {
                return -1;
            }
            return buffer[bufferIndex++];
        }
    }
}

