import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m1 = scanner.nextInt();
        int m2 = scanner.nextInt();
        DSU d1 = new DSU(n);
        DSU d2 = new DSU(n);
        d1.makeSet();
        d2.makeSet();

        boolean flag = false;
        for (int i = 0; i < m1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            if (d1.union(u, v) == -1)
                flag = true;
        }
        for (int i = 0; i < m2; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            if (d2.union(u, v) == -1)
                flag = true;
        }
        if (flag) {
            System.out.println(0);
            return;
        }

        List<int[]> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int y = d1.findParent(j);
                int y1 = d1.findParent(y);
                int x = d2.findParent(j);
                int x1 = d2.findParent(x);

                if (d1.union(i, j) == -1)
                    d1.parent[y] = y1;
                else if (d2.union(i, j) == -1) {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                } else {
                    d1.union(i, j);
                    d2.union(i, j);
                    result.add(new int[]{i, j});
                }
            }
        }

        System.out.println(result.size());
        for (int[] pair : result) {
            System.out.println(pair[0] + " " + pair[1]);
        }
    }

    static class DSU {
        int[] parent;

        public DSU(int n) {
            this.parent = new int[n + 1];
        }

        public void makeSet() {
            for (int i = 1; i <= parent.length - 1; i++) {
                parent[i] = i;
            }
        }

        public int findParent(int node) {
            if (node == parent[node])
                return node;

            parent[node] = findParent(parent[node]);
            return parent[node];
        }

        public int union(int u, int v) {
            int u_parent = findParent(u);
            int v_parent = findParent(v);

            if (u_parent != v_parent) {
                parent[v_parent] = u_parent;
                return 0;
            } else {
                return -1;
            }
        }

        public void checkComponent(int u, int v) {
            if (findParent(u) != findParent(v))
