                fastIO.println((long) arr[0] * arr[1]);
            } else {
                long res = -1;
                for (int k = 0; k < n - 1; k++) {
                    long product = (long) Math.max(arr[k + 1], arr[k]) * Math.min(arr[k + 1], arr[k]);
                    if (product > res) {
                        res = product;
                    }
                }
                fastIO.println(res);
            }
        }
    }

    static class FastIO extends PrintWriter {
        private InputStream in;
        private byte[] buffer;
        private int bufferSize, bufferIndex;

        public FastIO(InputStream in, OutputStream out) {
            super(out);
            this.in = in;
            this.bufferSize = 8192;
            this.buffer = new byte[bufferSize];
            this.bufferIndex = bufferSize;
        }

        private int read() throws IOException {
            if (bufferIndex >= bufferSize) {
                bufferIndex = 0;
                bufferSize = in.read(buffer);
            }
            if (bufferSize == -1) return -1;
            return buffer[bufferIndex++];
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }
}

import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        boolean wbPoss = n > 1;
        boolean bwPoss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = n > 1;

        for (int i = 0; i < n; i++) {
            String s = scanner.nextLine().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }

            if (s.charAt(1) == 'B') {
                b++;
                bwPoss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                wbPoss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }

            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss) {
            numBadPoss = (int) ((modPow(2, free, MOD) - (bwPoss ? 1 : 0) - (wbPoss ? 1 : 0) + MOD) % MOD);
        } else {
            numBadPoss = 0;
        }

        System.out.println((choose(q, wNeeded, MOD) - numBadPoss + MOD) % MOD);
    }

    private static int[] egcd(int a, int b) {
        if (a == 0) {
            return new int[]{b, 0, 1};
        } else {
            int[] result = egcd(b % a, a);
            int g = result[0];
            int y = result[1];
            int x = result[2];
            return new int[]{g, x - (b / a) * y, y};
        }
    }

    private static int modinv(int a, int m) {
        int[] result = egcd(a, m);
        int g = result[0];
        int x = result[1];
        if (g != 1) {
            throw new RuntimeException("modular inverse does not exist");
        } else {
            return (x % m + m) % m;
        }
    }

    private static int choose(int n, int k, int p) {
        if (k == 0) {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y > n - k; y--) {
            x = (x * y) % p;
        }
        long d = 1;
        for (int i = 2; i <= k; i++) {
            d = (d * i) % p;
        }
        return (int) ((x * modinv((int) d, p)) % p);
    }

    private static long modPow(long base, int exp, int modulus) {
        if (modulus == 1) return 0;
        long result = 1;
        base = base % modulus;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % modulus;
            exp >>= 1;
            base = (base * base) % modulus;
        }
        return result;
    }
}

