        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (gcd(Math.abs(p[i][0] - p[j][0]), Math.abs(p[i][1] - p[j][1])) % 4 == 0) {
                    cnt++;
