use std::io::{self, Read, Write};

struct FastIO {
    buffer: Vec<u8>,
    read_pos: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; 8192];
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let mut fast_io = FastIO { buffer, read_pos: 0 };
        fast_io.read_next_chunk(&mut handle);
        fast_io
    }

    fn read_next_chunk(&mut self, handle: &mut dyn Read) {
        self.buffer[self.read_pos..].fill(0);
        let bytes_read = handle.read(&mut self.buffer[self.read_pos..]).unwrap();
        self.buffer.truncate(self.read_pos + bytes_read);
    }

    fn read_to_end(&mut self, handle: &mut dyn Read) -> String {
        loop {
            if self.read_pos >= self.buffer.len() {
                self.read_next_chunk(handle);
                if self.buffer.is_empty() {
                    break;
                }
            }
            let end = self.buffer[self.read_pos..]
                .iter()
                .position(|&b| b == b'\n' || b == b'\0')
                .unwrap_or(self.buffer.len() - self.read_pos);
            let line = String::from_utf8_lossy(&self.buffer[self.read_pos..self.read_pos + end]).to_string();
            self.read_pos += end + 1;
            if !line.is_empty() {
                return line.trim_end().to_string();
            }
        }
    }

    fn read_line(&mut self, handle: &mut dyn Read) -> String {
        loop {
            if self.read_pos >= self.buffer.len() {
                self.read_next_chunk(handle);
                if self.buffer.is_empty() {
                    break;
                }
            }
            let end = self.buffer[self.read_pos..]
                .iter()
                .position(|&b| b == b'\n')
                .unwrap_or(self.buffer.len() - self.read_pos);
            let line = String::from_utf8_lossy(&self.buffer[self.read_pos..self.read_pos + end]).to_string();
            self.read_pos += end + 1;
            if !line.is_empty() {
                return line.trim_end().to_string();
            }
        }
    }
}

