use std::io::{self, Read, Write};

struct FastIO {
    buffer: Vec<u8>,
    pos: usize,
}

impl FastIO {
    fn new() -> Self {
        let mut buffer = vec![0; 8192];
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        let bytes_read = handle.read(&mut buffer).unwrap();
        buffer.resize(bytes_read, 0);
        FastIO { buffer, pos: 0 }
    }

    fn read_line(&mut self) -> String {
        let mut line = String::new();
        while self.pos < self.buffer.len() {
            if self.buffer[self.pos] == b'\n' {
                line.push_str(std::str::from_utf8(&self.buffer[self.pos - line.len()..self.pos]).unwrap());
                self.pos += 1;
                return line;
            }
            line.push(self.buffer[self.pos] as char);
            self.pos += 1;
        }
        if !line.is_empty() {
            line
        } else {
            panic!("Unexpected end of input");
        }
    }

    fn write(&mut self, data: &str) {
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        handle.write_all(data.as_bytes()).unwrap();
    }
}

fn main() {
