    FastReader(std::istream& _stream = std::cin) : stream(_stream) {}

    std::string next() {
        if (!iss.eof()) {
            std::string token;
            iss >> token;
            return token;
        }
        getline(stream, line);
        iss.str(line);
        iss.clear();
        std::string token;
        iss >> token;
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        if (!iss.eof()) {
            std::string line;
            getline(iss, line);
            return line;
        }
        getline(stream, line);
        return line;
    }
};

void reverse(std::vector<int>& a, int r) {
    for (int i = 0; i <= r / 2; ++i) {
        int l = i, h = r - i;
        std::swap(a[l], a[h]);
    }
}

