class Dsu {
public:
    std::vector<int> parent;

    Dsu(int n) : parent(n + 1) {}

    void make_set() {
        for (int i = 1; i <= parent.size() - 1; ++i) {
            parent[i] = i;
        }
    }

    int find_parent(int node) {
        if (node == parent[node])
            return node;

        parent[node] = find_parent(parent[node]);
        return parent[node];
    }

    int Union(int u, int v) {
        int u_parent = find_parent(u);
        int v_parent = find_parent(v);

        if (u_parent != v_parent) {
            parent[v_parent] = u_parent;
            return 0;
        } else {
            return -1;
        }
    }

    void check_component(int u, int v) {
        if (find_parent(u) != find_parent(v))
            std::cout << "Both belongs to different components" << std::endl;
        else
            std::cout << "same component" << std::endl;
    }

    void re_union(int u, int v) {}
};

