class FastIO {
private:
    static const int BUFSIZE = 8192;
    std::istream& _inputStream;
    std::ostream& _outputStream;
    char _buffer[BUFSIZE];
    int _bufferSize;
    int _bufferIndex;

public:
    FastIO(std::istream& inputStream, std::ostream& outputStream)
        : _inputStream(inputStream), _outputStream(outputStream), _bufferSize(0), _bufferIndex(0) {}

    std::string ReadLine() {
        std::ostringstream oss;
        while (true) {
            if (_bufferIndex >= _bufferSize) {
                _bufferSize = _inputStream.read(_buffer, BUFSIZE).gcount();
                _bufferIndex = 0;
            }
            if (_bufferSize == 0) break;

            int newlineIndex = std::find(_buffer + _bufferIndex, _buffer + _bufferSize, '\n') - _buffer;
            if (newlineIndex >= 0) {
                oss.write(_buffer + _bufferIndex, newlineIndex - _bufferIndex + 1);
                _bufferIndex = newlineIndex + 1;
                break;
            } else {
                oss.write(_buffer + _bufferIndex, _bufferSize - _bufferIndex);
                _bufferIndex = _bufferSize;
            }
        }
        return oss.str();
    }

    void WriteLine(long value) {
        _outputStream << value << '\n';
    }
};

