class FastIO {
    private let stream: InputStream
    private var buffer = Data()
    private let readBufferSize = 8192

    init(stream: InputStream) {
        self.stream = stream
        self.stream.open()
    }

    func readToEnd() -> String {
        while self.readData() > 0 {}
        return String(data: self.buffer, encoding: .ascii)!
    }

    func readLine() -> String? {
        var line = ""
        while true {
            if let c = self.readChar(), c != "\n" {
                line.append(c)
            } else {
                break
            }
        }
        return line.isEmpty ? nil : line
    }

    private func readData() -> Int {
        var data = Data(count: readBufferSize)
        let bytesRead = stream.read(into: &data)
        if bytesRead > 0 {
            buffer.append(data.prefix(bytesRead))
        }
        return bytesRead
    }

    private func readChar() -> Character? {
        while buffer.isEmpty && readData() > 0 {}
        guard !buffer.isEmpty else { return nil }
        let c = buffer.removeFirst()
        return String(UnicodeScalar(c))!
    }
}

