            for i in 0..<n {
                if let line = readLine() {
                    for j in 0..<m {
                        let ch = line[line.index(line.startIndex, offsetBy: j)]
                        d[i][j] = ch == "R" ? -1 : (ch == "U" ? -2 : (ch == "L" ? -3 : -4))
                    }
                }
            }

            var r = 0
            var pos = (0, 0)

            for i in 0..<n {
                for j in 0..<m {
                    var a = i
                    var b = j
                    let p = d[i][j]
                    var c = 0
                    var st: [(Int, Int)] = []

                    var currentP = p
                    while currentP < 0 {
                        d[a][b] = 0
                        st.append((a, b))

                        switch currentP {
                        case -1: b += 1
                        case -2: a -= 1
                        case -3: b -= 1
                        default: a += 1
                        }

