class FastIO {
    private let inputStream: FileHandle
    private let outputStream: FileHandle
    private var buffer = Data(capacity: 8192)

    init(inputStream: FileHandle, outputStream: FileHandle) {
        self.inputStream = inputStream
        self.outputStream = outputStream
    }

    func readLine() -> String? {
        var line = ""
        while true {
            let data = inputStream.readData(upToCount: 8192)
            if data.isEmpty { break }
            buffer.append(data)
            if let index = buffer.range(of: "\n".data(using: .ascii)!, options: [], in: buffer.startIndex..<buffer.endIndex)?.upperBound {
                line += String(data: buffer.subdata(in: buffer.startIndex..<index), encoding: .ascii)!
                buffer.removeSubrange(buffer.startIndex..<index)
                break
            }
        }
        return line.isEmpty ? nil : line.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func write(_ string: String) {
        if let data = (string + "\n").data(using: .ascii) {
            outputStream.write(data)
        }
    }
}

