BUFSIZE = 8192

class FastIO:
    def __init__(self):
        self.buffer = bytearray(BUFSIZE)
        self.pos = 0
        self.end = 0

    def _read(self):
        while True:
            n = sys.stdin.readinto(self.buffer[self.end:])
            if not n:
                break
            self.end += n

    def readline(self):
        result = bytearray()
        while True:
            if self.pos >= self.end:
                self._read()
                if self.pos >= self.end:
                    break
            while self.pos < self.end and self.buffer[self.pos] != ord('\n'):
                result.append(self.buffer[self.pos])
                self.pos += 1
            if self.pos < self.end:
                self.pos += 1
                break
        return result.decode()

