const BUFSIZE = 8192;

class FastIO {
    private buffer: Uint8Array;
    private pos: number;
    private end: number;

    constructor() {
        this.buffer = new Uint8Array(BUFSIZE);
        this.pos = 0;
        this.end = 0;
    }

    async read(): Promise<void> {
        while (true) {
            const n = await process.stdin.read({ buffer: this.buffer, offset: this.end, length: BUFSIZE - this.end });
            if (n === null || n === 0) break;
            this.end += n;
        }
    }

    async readline(): Promise<string> {
        let result = '';
        while (this.pos >= this.end) await this.read();
        while (true) {
            while (this.pos < this.end && this.buffer[this.pos] !== 10) {
                result += String.fromCharCode(this.buffer[this.pos]);
                this.pos++;
            }
            if (this.pos < this.end) {
                this.pos++; // Skip the newline character
                break;
            }
            await this.read();
        }
        return result;
    }

    isEmpty(): boolean {
        return this.pos >= this.end;
    }
}

