            const dx = Math.abs(p[i][0] - p[j][0]);
            const dy = Math.abs(p[i][1] - p[j][1]);
            if (gcd(dx, dy) % 4 === 0) {
                r[i][j] = 1;
                q[i]++;
                ans += n - 2;
