const MOD = 1_000_000_007
const INF = 1 << 60

type DSU struct {
	parent []int
}

func NewDSU(n int) *DSU {
	dsu := &DSU{parent: make([]int, n+1)}
	for i := 1; i <= n; i++ {
		dsu.parent[i] = i
	}
	return dsu
}

func (d *DSU) FindParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.FindParent(d.parent[node])
	return d.parent[node]
}

func (d *DSU) Union(u, v int) bool {
	uParent := d.FindParent(u)
	vParent := d.FindParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return true
	}
	return false
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m1, m2 int
	fmt.Fscanf(reader, "%d %d %d\n", &n, &m1, &m2)

	dsu1 := NewDSU(n)
	dsu2 := NewDSU(n)

	flag := 0

	for i := 0; i < m1; i++ {
		var u, v int
		fmt.Fscanf(reader, "%d %d\n", &u, &v)
		if !dsu1.Union(u, v) {
			flag = 1
		}
	}

	for i := 0; i < m2; i++ {
		var u, v int
		fmt.Fscanf(reader, "%d %d\n", &u, &v)
		if !dsu2.Union(u, v) {
			flag = 1
		}
	}

	if flag != 0 {
		fmt.Fprintln(writer, "0")
		return
	}

	var edges [][]int

	for i := 1; i <= n; i++ {
		for j := i + 1; j <= n; j++ {
			y := dsu1.FindParent(j)
			y1 := dsu1.FindParent(y)
			x := dsu2.FindParent(j)
			x1 := dsu2.FindParent(x)

			if !dsu1.Union(i, j) {
				dsu1.parent[y] = y1
			} else if !dsu2.Union(i, j) {
				dsu2.parent[x] = x1
				dsu1.parent[y] = y1
			} else {
				dsu1.Union(i, j)
				dsu2.Union(i, j)
				edges = append(edges, []int{i, j})
			}
		}
	}

	fmt.Fprintln(writer, len(edges))
	for _, edge := range edges {
		fmt.Fprintf(writer, "%d %d\n", edge[0], edge[1])
	}
}

