const MOD = 998244353

func binPow(a, b int64) int64 {
	var res int64 = 1
	for b > 0 {
		a %= MOD
		if b&1 == 1 {
			res = (res * a) % MOD
		}
		b >>= 1
		a = (a * a) % MOD
	}
	return res
}

func modInverse(a int64) int64 {
	return binPow(a, MOD-2)
}

func mul(a, b int64) int64 {
	return (a * b) % MOD
}

func nCr(n, r int, fact, invFact []int64) int64 {
	res := mul(fact[n], invFact[r])
	res = mul(res, invFact[n-r])
	return res
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	var n int
	fmt.Sscanf(scanner.Text(), "%d", &n)

	ls := make([]string, n)
	black, white := 0, 0
	full := false

	for i := 0; i < n; i++ {
		scanner.Scan()
		line := scanner.Text()
		ls[i] = line
		if line[0] == 'W' {
			white++
		}
		if line[0] == 'B' {
			black++
		}
		if line[1] == 'W' {
			white++
		}
		if line[1] == 'B' {
			black++
		}
		if line[0] != '?' && line[0] == line[1] {
			full = true
		}
	}

	if black > n || white > n {
		fmt.Println(0)
		return
	}

	fact := make([]int64, 2*n+1)
	invFact := make([]int64, 2*n+1)
	fact[0], invFact[0] = 1, 1

	for i := 1; i <= 2*n; i++ {
		fact[i] = mul(fact[i-1], int64(i))
		invFact[i] = modInverse(fact[i])
	}

	empty := 2*n - black - white
	ans := nCr(empty, n-black, fact, invFact)

	if full {
		fmt.Println(ans)
		return
	}

	invalid := int64(1)
	wb, bw := true, true

	for _, line := range ls {
		if line[0] == '?' && line[1] == '?' {
			invalid = mul(invalid, 2)
		}
		if line[0] == 'B' || line[1] == 'W' {
			wb = false
		}
		if line[0] == 'W' || line[1] == 'B' {
			bw = false
		}
	}

	if wb {
		invalid--
	}
	if bw {
		invalid--
	}

	ans -= invalid
	fmt.Println(ans)
}

