public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());
        while (t-- > 0) {
            String[] input = br.readLine().split(" ");
            long n = Long.parseLong(input[0]);
            long s = Long.parseLong(input[1]);
            System.out.println(s / ((n + 2) / 2));
        }
    }

    public static int[] nextLargerElement(int[] arr, boolean f) {
        Stack<Integer> stack = new Stack<>();
        int[] ans = new int[arr.length];
        Arrays.fill(ans, -1);
        for (int i = 0; i < arr.length; i++) {
            while (!stack.isEmpty() && arr[stack.peek()] < arr[i]) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                ans[i] = stack.peek();
            }
            stack.push(i);
        }
        if (f) {
            for (int i = 0; i < arr.length; i++) {
                if (ans[i] != -1) {
                    ans[i] = arr.length - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, Integer p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (!Objects.equals(j, p)) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += (long) ans * (ans - 1) / 2;
        }
        return a1;
    }
}

