import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;
    private static final long INF = 1L << 60;

    static class DSU {
        int[] parent;

        public DSU(int n) {
            this.parent = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        public int findParent(int node) {
            if (node == parent[node]) return node;
            return parent[node] = findParent(parent[node]);
        }

        public int union(int u, int v) {
            int uParent = findParent(u);
            int vParent = findParent(v);

            if (uParent != vParent) {
                parent[vParent] = uParent;
                return 0;
            } else {
                return -1;
            }
        }

        public void checkComponent(int u, int v) {
            if (findParent(u) != findParent(v)) {
                System.out.println("Both belongs to different components");
            } else {
                System.out.println("same component");
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String[] input = br.readLine().split("\\s+");
        int n = Integer.parseInt(input[0]);
        int m1 = Integer.parseInt(input[1]);
        int m2 = Integer.parseInt(input[2]);

        DSU d1 = new DSU(n);
        DSU d2 = new DSU(n);

        int flag = 0;
        for (int i = 0; i < m1; i++) {
            input = br.readLine().split("\\s+");
            int u = Integer.parseInt(input[0]);
            int v = Integer.parseInt(input[1]);
            if (d1.union(u, v) == -1) flag = 1;
        }

        for (int i = 0; i < m2; i++) {
            input = br.readLine().split("\\s+");
            int u = Integer.parseInt(input[0]);
            int v = Integer.parseInt(input[1]);
            if (d2.union(u, v) == -1) flag = 1;
        }

        if (flag != 0) {
            out.println(0);
            out.close();
            return;
        }

        List<int[]> edges = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int y = d1.findParent(j);
                int y1 = d1.findParent(y);
                int x = d2.findParent(j);
                int x1 = d2.findParent(x);

                if (d1.union(i, j) == -1) {
                    d1.parent[y] = y1;
                } else if (d2.union(i, j) == -1) {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                } else {
                    d1.union(i, j);
                    d2.union(i, j);
                    edges.add(new int[]{i, j});
                }
            }
        }

        out.println(edges.size());
        for (int[] edge : edges) {
            out.println(edge[0] + " " + edge[1]);
        }

        out.close();
    }
}

