import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        List<String> ls = new ArrayList<>();
        int black = 0;
        int white = 0;
        boolean full = false;

        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            ls.add(line);
            if (line.charAt(0) == 'W') white++;
            if (line.charAt(0) == 'B') black++;
            if (line.charAt(1) == 'W') white++;
            if (line.charAt(1) == 'B') black++;
            if (line.charAt(0) != '?' && line.charAt(0) == line.charAt(1)) full = true;
        }

        if (black > n || white > n) {
            System.out.println("0");
            return;
        }

        long[] fact = new long[2 * n + 1];
        long[] invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= 2 * n; i++) {
            fact[i] = mul(fact[i - 1], i);
            invFact[i] = modInverse(fact[i]);
        }

        int empty = 2 * n - black - white;
        long ans = nCr(empty, n - black, fact, invFact);

        if (full) {
            System.out.println(ans);
            return;
        }

        long invalid = 1;
        boolean wb = true;
        boolean bw = true;

        for (String line : ls) {
            if (line.charAt(0) == '?' && line.charAt(1) == '?') {
                invalid = mul(invalid, 2);
            }
            if (line.charAt(0) == 'B' || line.charAt(1) == 'W') wb = false;
            if (line.charAt(0) == 'W' || line.charAt(1) == 'B') bw = false;
        }

        if (wb) invalid--;
        if (bw) invalid--;

        ans -= invalid;
        System.out.println(ans);
    }

    private static long binPow(long a, long b) {
        long res = 1;
        while (b > 0) {
            a %= MOD;
            if ((b & 1) == 1) {
                res = mul(res, a);
            }
            b >>= 1;
            a = mul(a, a);
        }
        return res;
    }

    private static long modInverse(long a) {
        return binPow(a, MOD - 2);
    }

    private static long mul(long a, long b) {
        return (a * b) % MOD;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        long res = mul(fact[n], invFact[r]);
        res = mul(res, invFact[n - r]);
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;
    private static byte[] buffer = new byte[BUFSIZE];
    private static int pos = 0, end = 0;

    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO();
        PrintWriter out = new PrintWriter(System.out);

        int t = inp(io);
        while (t-- > 0) {
            int n = inp(io);
            int[] l = inlt(io, n);
            int s = l[0];
            for (int i = 1; i < n; i++) {
                s &= l[i];
            }
            out.println(s);
        }

        out.close();
    }

    private static class FastIO extends InputStream {
        public FastIO() throws IOException {
            end = System.in.read(buffer);
        }

        @Override
        public int read() throws IOException {
            if (pos >= end) {
                pos = 0;
                end = System.in.read(buffer);
                if (end < 0) return -1;
            }
            return buffer[pos++];
        }
    }

    private static void print(Object... args) {
        StringJoiner sj = new StringJoiner(" ");
        for (Object arg : args) {
            sj.add(arg.toString());
        }
        System.out.println(sj.toString());
    }

    private static int inp(FastIO io) throws IOException {
        int c;
        while ((c = io.read()) < '0' || c > '9') ;
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
        } while ((c = io.read()) >= '0' && c <= '9');
        return res;
    }

    private static String inps(FastIO io) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = io.read()) != '\n' && c != -1) {
            sb.append((char) c);
        }
        return sb.toString().trim();
    }

    private static int[] inlt(FastIO io, int n) throws IOException {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = inp(io);
        }
        return arr;
    }

    private static List<Character> insr(FastIO io) throws IOException {
        List<Character> list = new ArrayList<>();
        int c;
        while ((c = io.read()) != '\n' && c != -1) {
            list.add((char) c);
        }
        return list;
    }

    private static int[] invr(FastIO io) throws IOException {
        String[] parts = inps(io).split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine().trim());
        int[][] p = new int[n][2];

        for (int i = 0; i < n; i++) {
            String[] coords = scanner.nextLine().trim().split("\\s+");
            p[i][0] = Integer.parseInt(coords[0]);
            p[i][1] = Integer.parseInt(coords[1]);
        }

        int ans = 0;
        int cnt = 0;
        int[][] r = new int[n][n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dx = Math.abs(p[i][0] - p[j][0]);
                int dy = Math.abs(p[i][1] - p[j][1]);
                if (gcd(dx, dy) % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }

    public static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

