        {
            string[] input = reader.ReadLine().Split();
            int n = int.Parse(input[0]);
            int s = int.Parse(input[1]);
            Console.WriteLine(s / ((n + 2) / 2));
        }
    }

    public static List<int> NextLargerElement(int[] arr, int n, bool f)
    {
        Stack<int> stack = new Stack<int>();
        int[] ans = new int[n];
        for (int i = 0; i < n; i++)
        {
            ans[i] = -1;
        }
        for (int i = 0; i < n; i++)
        {
            while (stack.Count > 0 && arr[stack.Peek()] < arr[i])
            {
                stack.Pop();
            }
            if (stack.Count > 0)
            {
                ans[i] = stack.Peek();
            }
            stack.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = (n - 1) - ans[i];
                }
            }
        }
        return new List<int>(ans);
    }

    public static int Dfs(int i, List<List<int>> adj, int p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (var j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += (ans * (ans - 1)) / 2;
        }
        return a1;
    }
}

