                                d[item.Item1, item.Item2] = c - ii;
                                ii++;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0)
                    {
                        bool flag = false;
                        int jj = 0;
                        int ii = 0;
                        foreach (var item in st)
                        {
                            d[item.Item1, item.Item2] = flag ? c - jj : c - ii;
                            if (item.Item1 == a && item.Item2 == b)
                            {
                                flag = true;
                                jj = ii;
                            }
                            ii++;
                        }
                    }

                    if (p > 0)
                    {
                        int ii = 0;
                        foreach (var item in st)
                        {
                            d[item.Item1, item.Item2] = p + c - ii;
                            ii++;
                        }
                    }

                    if (d[i, j] > r)
                    {
                        r = d[i, j];
                        posX = i;
                        posY = j;
                    }
                }
            }

            Console.WriteLine($"{posX + 1} {posY + 1} {r}");
        }
