using System;
using System.Collections.Generic;

class Program
{
    const int Mod = 998244353;

    static long BinPow(long a, long b)
    {
        long res = 1;
        while (b > 0)
        {
            a %= Mod;
            if ((b & 1) == 1)
                res = (res * a) % Mod;
            b >>= 1;
            a = (a * a) % Mod;
        }
        return res;
    }

    static long ModInverse(long a)
    {
        return BinPow(a, Mod - 2);
    }

    static long Mul(long a, long b)
    {
        return (a * b) % Mod;
    }

    static long NCr(int n, int r, List<long> fact, List<long> invFact)
    {
        long res = Mul(fact[n], invFact[r]);
        res = Mul(res, invFact[n - r]);
        return res;
    }

    static void Main()
    {
        var reader = Console.In;
        var writer = Console.Out;

        int n = int.Parse(reader.ReadLine());
        List<string> ls = new List<string>();
        int black = 0;
        int white = 0;
        bool full = false;

        for (int i = 0; i < n; i++)
        {
            string line = reader.ReadLine();
            ls.Add(line);
            if (line[0] == 'W') white++;
            if (line[0] == 'B') black++;
            if (line[1] == 'W') white++;
            if (line[1] == 'B') black++;
            if (line[0] != '?' && line[0] == line[1]) full = true;
        }

        if (black > n || white > n)
        {
            writer.WriteLine(0);
            return;
        }

        List<long> fact = new List<long>(new long[2 * n + 1]);
        List<long> invFact = new List<long>(new long[2 * n + 1]);
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= 2 * n; i++)
        {
            fact[i] = Mul(fact[i - 1], i);
            invFact[i] = ModInverse(fact[i]);
        }

        int empty = 2 * n - black - white;
        long ans = NCr(empty, n - black, fact, invFact);

        if (full)
        {
            writer.WriteLine(ans);
            return;
        }

        long invalid = 1;
        bool wb = true;
        bool bw = true;

        foreach (var line in ls)
        {
            if (line[0] == '?' && line[1] == '?') invalid = Mul(invalid, 2);
            if (line[0] == 'B' || line[1] == 'W') wb = false;
            if (line[0] == 'W' || line[1] == 'B') bw = false;
        }

        if (wb) invalid--;
        if (bw) invalid--;

        ans -= invalid;
        writer.WriteLine(ans);
    }
}

