class Program
{
    static void Main()
    {
        var reader = Console.In;
        int n = int.Parse(reader.ReadLine());
        List<(int, int)> p = new List<(int, int)>();
        for (int i = 0; i < n; i++)
        {
            var parts = reader.ReadLine().Split(' ');
            int x = int.Parse(parts[0]);
            int y = int.Parse(parts[1]);
            p.Add((x, y));
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int dx = Math.Abs(p[i].Item1 - p[j].Item1);
                int dy = Math.Abs(p[i].Item2 - p[j].Item2);
                if (Gcd(dx, dy) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

