                    int jj = 0;
                    bool flag = false;
                    for (size_t ii = 0; ii < st.size(); ++ii) {
                        auto [x, y] = st[ii];
                        d[x][y] = flag ? c - jj : c - static_cast<int>(ii);
                        if (x == a && y == b) {
                            flag = true;
                            jj = static_cast<int>(ii);
                        }
                    }
                }

                if (p > 0) {
                    for (size_t ii = 0; ii < st.size(); ++ii) {
                        auto [x, y] = st[ii];
                        d[x][y] = p + c - static_cast<int>(ii);
                    }
                }

                if (d[i][j] > r) {
                    r = d[i][j];
                    pos_i = i;
                    pos_j = j;
