const int MOD = 1e9 + 7;
const long long INF = 1LL << 60;

class DSU {
public:
    std::vector<int> parent;

    DSU(int n) : parent(n + 1) {
        for (int i = 1; i <= n; ++i) {
            parent[i] = i;
        }
    }

    int findParent(int node) {
        if (node == parent[node]) return node;
        return parent[node] = findParent(parent[node]);
    }

    int Union(int u, int v) {
        int uParent = findParent(u);
        int vParent = findParent(v);

        if (uParent != vParent) {
            parent[vParent] = uParent;
            return 0;
        } else {
            return -1;
        }
    }

    void checkComponent(int u, int v) {
        if (findParent(u) != findParent(v)) {
            std::cout << "Both belongs to different components\n";
        } else {
            std::cout << "same component\n";
        }
    }
};

int main() {
    DSU d1(0), d2(0);
    int n, m1, m2;
    std::cin >> n >> m1 >> m2;
    d1 = DSU(n);
    d2 = DSU(n);

    int flag = 0;
    for (int i = 0; i < m1; ++i) {
        int u, v;
        std::cin >> u >> v;
        if (d1.Union(u, v) == -1) flag = 1;
    }

    for (int i = 0; i < m2; ++i) {
        int u, v;
        std::cin >> u >> v;
        if (d2.Union(u, v) == -1) flag = 1;
    }

    if (flag) {
        std::cout << "0\n";
        return 0;
    }

    std::vector<std::pair<int, int>> result;
    for (int i = 1; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            int y = d1.findParent(j);
            int y1 = d1.findParent(y);
            int x = d2.findParent(j);
            int x1 = d2.findParent(x);

            if (d1.Union(i, j) == -1) {
                d1.parent[y] = y1;
            } else if (d2.Union(i, j) == -1) {
                d2.parent[x] = x1;
                d1.parent[y] = y1;
            } else {
                d1.Union(i, j);
                d2.Union(i, j);
                result.emplace_back(i, j);
            }
        }
    }

    std::cout << result.size() << "\n";
    for (const auto& p : result) {
