const int BUFSIZE = 8192;

class FastIO {
private:
    char buffer[BUFSIZE];
    int pos, end;
public:
    FastIO() : pos(0), end(0) {}

    void read() {
        end = std::cin.read(buffer, BUFSIZE).gcount();
        pos = 0;
    }

    std::string readline() {
        std::string result;
        while (true) {
            if (pos >= end) {
                read();
                if (end == 0) break;
            }
            while (pos < end && buffer[pos] != '\n') {
                result += buffer[pos++];
            }
            if (pos < end) {
                pos++;
                break;
            }
        }
        return result;
    }

    bool is_empty() const {
        return pos >= end;
    }
};

