func nextLargerElement(_ arr: [Int], _ n: Int, _ f: Bool) -> [Int] {
    var s: [Int] = []
    var ans = Array(repeating: -1, count: n)
    for i in 0..<n {
        while !s.isEmpty && arr[s.last!] < arr[i] {
            s.removeLast()
        }
        if !s.isEmpty {
            ans[i] = s.last!
        }
        s.append(i)
    }
    if f {
