class FastIO {
    private var buffer: Data
    private var pos: Int

    init() {
        self.buffer = Data()
        self.pos = 0
    }

    func read() throws {
        let input = FileHandle.standardInput.readDataToEndOfFile()
        buffer.append(input)
    }

    func readline() throws -> String {
        while pos < buffer.count && buffer[pos] != 10 {
            try read()
        }

        if pos >= buffer.count {
            return ""
        }

        let start = pos
        while pos < buffer.count && buffer[pos] != 10 {
            pos += 1
        }

        let line = String(data: buffer[start..<pos], encoding: .utf8)!
        pos += 1 // Skip newline character
        return line
    }
}

