const MOD = 998244353;

function egcd(a: number, b: number): [number, number, number] {
    if (a === 0) {
        return [b, 0, 1];
    } else {
        const [g, y, x] = egcd(b % a, a);
        return [g, x - Math.floor(b / a) * y, y];
    }
}

function modinv(a: number, m: number): number {
    const [g, x, _] = egcd(a, m);
    if (g !== 1) {
        throw new Error("modular inverse does not exist");
    } else {
        return ((x % m) + m) % m;
    }
}

function choose(n: number, k: number, p: number): number {
    if (k === 0 || k === n) {
        return 1;
    }
    let x = n;
    for (let y = n - 1; y > n - k; y--) {
        x = (x * y) % p;
    }
    let d = 1;
    for (let i = 2; i <= k; i++) {
        d = (d * i) % p;
    }
    return (x * modinv(d, p)) % p;
}

