type Dsu struct {
	parent []int
}

func NewDsu(n int) *Dsu {
	d := &Dsu{parent: make([]int, n+1)}
	return d
}

func (d *Dsu) MakeSet() {
	for i := 1; i < len(d.parent); i++ {
		d.parent[i] = i
	}
}

func (d *Dsu) FindParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.FindParent(d.parent[node])
	return d.parent[node]
}

func (d *Dsu) Union(u, v int) int {
	uParent := d.FindParent(u)
	vParent := d.FindParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return 0
	} else {
		return -1
	}
}

func (d *Dsu) CheckComponent(u, v int) {
	if d.FindParent(u) != d.FindParent(v) {
		fmt.Println("Both belongs to different components")
	} else {
		fmt.Println("same component")
	}
}

