import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 998244353;
    private static BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        int t = readInt();
        while (t-- > 0) {
            solve();
        }
    }

    private static void solve() throws IOException {
        int n = readInt();
        int[] dp1 = new int[n + 2];
        int[] dp2 = new int[n + 2];
        dp1[0] = 1;
        for (int i : readIntArray()) {
            dp1[i + 1] = (int) ((long) dp1[i + 1] * 2 % MOD);
            dp1[i + 1] = (int) ((long) dp1[i + 1] + dp1[i]) % MOD;
            if (i > 0) {
                dp2[i - 1] = (int) ((long) dp2[i - 1] * 2 % MOD);
                dp2[i - 1] = (int) ((long) dp2[i - 1] + dp1[i - 1]) % MOD;
            }
            dp2[i + 1] = (int) ((long) dp2[i + 1] * 2 % MOD);
        }
        int ans = 0;
        for (int i = 0; i < n + 2; i++) {
            ans = (int) ((long) ans + dp1[i] + dp2[i]) % MOD;
        }
        System.out.println((ans - 1 + MOD) % MOD);
    }

    private static int readInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static int[] readIntArray() throws IOException {
        String[] tokens = nextLine().split(" ");
        int[] array = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            array[i] = Integer.parseInt(tokens[i]);
        }
        return array;
    }

    private static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private static String nextLine() throws IOException {
        return reader.readLine();
    }
}

import java.util.*;

public class Main {
    public static int[] nextLargerElement(int[] arr, int n, boolean f) {
        Stack<Integer> s = new Stack<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.peek()] < arr[i]) {
                s.pop();
            }
            if (!s.isEmpty()) {
                ans[i] = s.peek();
            }
            s.push(i);
        }
        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans[i] != -1) {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, int p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (j != p) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += (long) ans * (ans - 1) / 2; // Use long to prevent overflow
        }
        return a1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int s = scanner.nextInt();
            System.out.println(s / ((n + 2) / 2));
        }
    }
}

