import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        boolean wbPoss = true;
        boolean bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = true;

        for (int i = 0; i < n; i++) {
            String s = scanner.nextLine().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }

            if (s.charAt(s.length() - 1) == 'B') {
                b++;
                bwPoss = false;
            } else if (s.charAt(s.length() - 1) == 'W') {
                w++;
                wbPoss = false;
            } else if (s.charAt(s.length() - 1) == '?') {
                q++;
            }

            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(s.length() - 1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - b;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        long numBadPoss;
        if (anyBadPoss) {
            numBadPoss = powerOfTwoMod(free, MOD);
            numBadPoss -= (bwPoss ? 1 : 0) + (wbPoss ? 1 : 0);
        } else {
            numBadPoss = 0;
        }

        System.out.println((modularSubtract(choose(q, wNeeded, MOD), numBadPoss, MOD)));
    }

    private static long egcd(long a, long b, long[] xAndY) {
        if (a == 0) {
            xAndY[0] = 0;
            xAndY[1] = 1;
            return b;
        } else {
            long[] temp = new long[2];
            long gcd = egcd(b % a, a, temp);
            xAndY[0] = temp[1] - (b / a) * temp[0];
            xAndY[1] = temp[0];
            return gcd;
        }
    }

    private static long modinv(long a, long m) {
        long[] xAndY = new long[2];
        long g = egcd(a, m, xAndY);
        if (g != 1) {
            throw new IllegalArgumentException("modular inverse does not exist");
        } else {
            return (xAndY[0] % m + m) % m;
        }
    }

    private static long choose(int n, int k, int p) {
        if (k == 0 || k == n) {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y > n - k; y--) {
            x = (x * y) % p;
        }
        long d = 1;
        for (int i = 2; i <= k; i++) {
            d = (d * i) % p;
        }
        return (x * modinv(d, p)) % p;
    }

    private static long powerOfTwoMod(int exp, int mod) {
        long result = 1;
        long base = 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static long modularSubtract(long a, long b, int mod) {
        return ((a - b) % mod + mod) % mod;
    }
}

