}

fn read_int_array(input: &mut dyn BufRead) -> Vec<i64> {
    let mut buffer = String::new();
    input.read_line(&mut buffer).expect("Failed to read line");
    buffer.split_whitespace()
         .map(|s| s.parse().expect("Failed to parse integer"))
         .collect()
}

