            }
            dp2[i + 1] = (dp2[i + 1] * 2 % MOD) % MOD;
        }

        let mut ans = 0;
        for i in 0..=n + 1 {
            ans = (ans + dp1[i] + dp2[i]) % MOD;
        }
        println!("{}", (ans - 1 + MOD) % MOD);
    }
