fn next_larger_element(arr: &[i32], n: usize, f: bool) -> Vec<i32> {
    let mut s = Vec::new();
    let mut ans = vec![-1; n];
    for i in 0..n {
        while !s.is_empty() && arr[*s.last().unwrap()] < arr[i] {
            s.pop();
        }
        if let Some(&last) = s.last() {
            ans[i] = last as i32;
        }
        s.push(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = n as i32 - 1 - ans[i];
            }
        }
    }
    ans
}

