struct Dsu {
    parent: Vec<usize>,
}

impl Dsu {
    fn new(n: usize) -> Self {
        let mut dsu = Dsu { parent: vec![0; n + 1] };
        dsu.make_set();
        dsu
    }

    fn make_set(&mut self) {
        for i in 1..self.parent.len() {
            self.parent[i] = i;
        }
    }

    fn find_parent(&mut self, node: usize) -> usize {
        if node == self.parent[node] {
            return node;
        }
        self.parent[node] = self.find_parent(self.parent[node]);
        self.parent[node]
    }

    fn union(&mut self, u: usize, v: usize) -> bool {
        let u_parent = self.find_parent(u);
        let v_parent = self.find_parent(v);

        if u_parent != v_parent {
            self.parent[v_parent] = u_parent;
            true
        } else {
            false
        }
    }

    fn check_component(&mut self, u: usize, v: usize) {
        if self.find_parent(u) != self.find_parent(v) {
            println!("Both belongs to different components");
        } else {
            println!("same component");
        }
    }
}

