const MOD: i64 = 998244353;

fn egcd(a: i64, b: i64) -> (i64, i64, i64) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, x, y) = egcd(b % a, a);
        (g, x - (b / a) * y, y)
    }
}

fn modinv(a: i64, m: i64) -> i64 {
    let (_, x, _) = egcd(a, m);
    ((x % m + m) % m)
}

fn choose(n: i64, k: i64, p: i64) -> i64 {
    if k == 0 || k == n {
        return 1;
    }
    let mut x = n;
    for y in (n - k + 1..=n).rev() {
        x = x * y % p;
    }
    let mut d = 1;
    for i in 2..=k {
        d = d * i % p;
    }
    (x * modinv(d, p)) % p
}

fn solve() {
    use std::io::{self, BufRead};
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: i64 = lines.next().unwrap().expect("Failed to read line").trim().parse().unwrap();
    let mut wb_poss = true;
    let mut bw_poss = true;
    let mut w = 0;
    let mut b = 0;
    let mut q = 0;
    let mut free = 0;
    let mut any_bad_poss = true;

    for _ in 0..n {
        let s = lines.next().unwrap().expect("Failed to read line").trim().to_string();
        if s.starts_with('B') {
            b += 1;
            wb_poss = false;
        } else if s.starts_with('W') {
            w += 1;
            bw_poss = false;
        } else if s.starts_with('?') {
            q += 1;
        }

        if s.ends_with('B') {
            b += 1;
            bw_poss = false;
        } else if s.ends_with('W') {
            w += 1;
            bw_poss = false;
        } else if s.ends_with('?') {
            q += 1;
        }

        if s == "??" {
            free += 1;
        } else if s.starts_with(s.chars().nth(1).unwrap()) {
            any_bad_poss = false;
        }
    }

    let w_needed = n - b;
    if w_needed > q || w_needed < 0 {
        println!("0");
        return;
    }

    let num_bad_poss = if any_bad_poss {
        let mut num = 1 << free;
        num %= MOD;
        num -= (if bw_poss { 1 } else { 0 }) + (if wb_poss { 1 } else { 0 });
        if num < 0 {
            num += MOD;
        }
        num
    } else {
        0
    };

    println!("{}", (choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
}

