const int mod = 998244353;

std::tuple<int, int, int> egcd(int a, int b) {
    if (a == 0) {
        return {b, 0, 1};
    } else {
        auto [g, y, x] = egcd(b % a, a);
        return {g, x - (b / a) * y, y};
    }
}

int modinv(int a, int m) {
    auto [g, x, _] = egcd(a, m);
    if (g != 1) {
        throw std::runtime_error("modular inverse does not exist");
    } else {
        return (x % m + m) % m;
    }
}

int choose(int n, int k, int p) {
    if (k == 0 || k == n) {
        return 1;
    }
    long long x = n;
    for (int y = n - 1; y > n - k; --y) {
        x = (x * y) % p;
    }
    int d = 1;
    for (int i = 2; i <= k; ++i) {
        d = (d * i) % p;
    }
    return static_cast<int>((x * modinv(d, p)) % p);
}

void solve() {
    int n;
    std::cin >> n;
    bool wb_poss = true;
    bool bw_poss = true;
    int w = 0;
    int b = 0;
    int q = 0;
    int free = 0;
    bool any_bad_poss = true;

    for (int i = 0; i < n; ++i) {
        std::string s;
        std::cin >> s;
        if (s[0] == 'B') {
            b++;
            wb_poss = false;
        } else if (s[0] == 'W') {
            w++;
            bw_poss = false;
        } else if (s[0] == '?') {
            q++;
        }

        if (s.back() == 'B') {
            b++;
            bw_poss = false;
        } else if (s.back() == 'W') {
            w++;
            bw_poss = false;
        } else if (s.back() == '?') {
            q++;
        }

        if (s == "??" ) {
            free++;
        } else if (s[0] == s.back()) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - b;
    if (w_needed > q || w_needed < 0) {
        std::cout << 0 << '\n';
        return;
    }

    int num_bad_poss;
    if (any_bad_poss) {
        num_bad_poss = 1;
        for (int i = 0; i < free; ++i) {
            num_bad_poss = (num_bad_poss * 2) % mod;
        }
        num_bad_poss = (num_bad_poss - (bw_poss ? 1 : 0) - (wb_poss ? 1 : 0) + mod) % mod;
    } else {
        num_bad_poss = 0;
    }

    std::cout << (choose(q, w_needed, mod) - num_bad_poss + mod) % mod << '\n';
}

int main() {
    solve();
    return 0;
}

