    while (t-- > 0) {
        std::string line = readLine();
        int n, m, k;
        sscanf(line.c_str(), "%d %d %d", &n, &m, &k);

        int bigTablesStartingNum = 0;
        int bigTablesCount = n % m;
        int bigTableSize = 1 + n / m;

        int smallTablesCount = m - n % m;
        int smallTableSize = n / m;
        int peopleAtBigTables = bigTableSize * bigTablesCount;

        std::vector<int> bigTableNums(bigTableSize, -1);
        std::vector<int> smallTableNums(smallTableSize, -1);

        for (int round = 0; round < k; ++round) {
            int i = 0;
            for (int bt = 0; bt < bigTablesCount; ++bt) {
                for (int x = 0; x < bigTableSize; ++x) {
                    bigTableNums[x] = (bigTablesStartingNum + i++) % n + 1;
                }
                printTable(bigTableNums);
            }
            for (int st = 0; st < smallTablesCount; ++st) {
                for (int x = 0; x < smallTableSize; ++x) {
                    smallTableNums[x] = (bigTablesStartingNum + i++) % n + 1;
                }
                printTable(smallTableNums);
            }
            bigTablesStartingNum = (bigTablesStartingNum + peopleAtBigTables) % n;
        }
        std::cout << "\n";
    }
    return 0;
}

